import {describe,it,expect,vi} from 'vitest';
import {DatabaseSync} from 'node:sqlite';
import {mkdtempSync,mkdirSync,writeFileSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';import {join} from 'node:path';
import {WorkspaceEngine} from '../../../vendor/repo-wiki/packages/core/src/engine';
import {KnowledgeProjectPort} from '../../knowledgeProcess/projectPort';
import {KnowledgeBuildStore,hashKnowledgePayload} from './store';
import {KnowledgeKernelCoordinator,knowledgeModelIdentity} from './coordinator';
import type {KnowledgeModelBinding,StageExecutionRequest,StageExecutionResult} from '../../../shared/knowledgeKernelContracts';
const binding={bindingId:'b',expectedModel:'model',expectedConfiguration:'identity',model:{id:'model',name:'model',api:'openai-completions',provider:'test',reasoning:false,input:['text'],contextWindow:8192,maxTokens:1024,cost:{input:0,output:0,cacheRead:0,cacheWrite:0}}} as KnowledgeModelBinding;
describe('knowledge coordinator',()=>{
 it('creates one task per request and publishes an acknowledged staged graph',async()=>{
  const base=mkdtempSync(join(tmpdir(),'knowledge-coord-')),root=join(base,'src');mkdirSync(root);writeFileSync(join(root,'readme.md'),'# project\n');const engine=new WorkspaceEngine(join(base,'data'));const db=new DatabaseSync(':memory:');const store=new KnowledgeBuildStore(db,{controllerEpoch:'epoch'});const project=new KnowledgeProjectPort(engine);const p=engine.create_project(root,'en');const source=await project.prepare(p.id,'wiki');
  let attempted=0;const executeStage=async(req:StageExecutionRequest):Promise<StageExecutionResult>=>{const willFail=req.phase==='generate'&&attempted++===0;let payload:unknown={};const sources=[{path:'readme.md',hash:source.source.hashes['readme.md'],start:1,end:1}];if(req.phase==='overview')payload={summary:'A project',sources};if(req.phase==='plan')payload={items:[{id:'intro',title:'Intro',goal:'Explain',dependencies:[]}]};if(req.phase==='catalogue')payload={children:[]};if(req.phase==='generate')payload={markdown:'# Intro',sources};if(req.phase==='validate')payload={valid:true};return {version:1,taskId:req.taskId,fence:req.fence,phase:req.phase,itemId:req.itemId,stageAttempt:req.attempt,sequence:1,inputHash:req.inputHash,outputHash:hashKnowledgePayload(payload),payload,evidence:[{path:'readme.md',hash:sources[0].hash,startLine:1,endLine:1,kind:'read'}],dependencies:[],disposition:willFail?'failed':'prepared',...(willFail?{error:{code:'TRANSIENT',message:'retry',retriable:true}}:{})};};
  const c=new KnowledgeKernelCoordinator({store,project,bindModel:async()=>binding,executeStage,abortStage:async()=>{}});
  try{const request={version:1 as const,requestId:'r',projectId:p.id,domain:'wiki' as const,language:'en',intent:'generate' as const,confirmExternal:true as const,expectedModelIdentity:knowledgeModelIdentity(binding),expectedPlanToken:source.planToken};const first=await c.start(request);const again=await c.start(request);expect(again.run?.taskId).toBe(first.run?.taskId);await viWait(async()=>store.getTask(first.run!.taskId)?.state==='completed');expect((await c.snapshot(p.id,'wiki')).content.publishedCount).toBe(1);expect(attempted).toBe(2);}
  finally{await c.close();engine.close();db.close();rmSync(base,{recursive:true,force:true});}
 },30000);
});
async function viWait(check:()=>Promise<boolean>|boolean){for(let i=0;i<200;i++){if(await check())return;await new Promise(r=>setTimeout(r,50));}throw new Error('task did not complete');}

it.each([false,true])('records rejected page links as repairable candidates without leaving running items (v2=%s)',async useV2=>{
 const base=mkdtempSync(join(tmpdir(),'knowledge-invalid-link-')),root=join(base,'src');mkdirSync(root);writeFileSync(join(root,'readme.md'),'# project\n');const engine=new WorkspaceEngine(join(base,'data'));const db=new DatabaseSync(':memory:');const store=new KnowledgeBuildStore(db,{controllerEpoch:'epoch'});const project=new KnowledgeProjectPort(engine);const p=engine.create_project(root,'en');const source=await project.prepare(p.id,'wiki');let bad=true;let generated=0;const pipelineConfigHash=useV2?'knowledge-kernel-qoder-v2':'knowledge-kernel-v1';
 const executeStage=async(req:StageExecutionRequest):Promise<StageExecutionResult>=>{let payload:unknown={};const sources=[{path:'readme.md',hash:source.source.hashes['readme.md'],start:1,end:1}];if(req.phase==='overview')payload={summary:'Project',sources};if(req.phase==='plan')payload={items:[{id:'intro',title:'Intro',goal:'Explain',dependencies:[]}]};if(req.phase==='catalogue')payload={children:req.itemId==='catalogue:root'?[{id:'intro',title:'Intro',goal:'Explain',dependencies:[]}]:[]};if(req.phase==='generate'){generated++;payload={markdown:bad?'[Missing](../../missing.md)':'# Intro',sources};}if(req.phase==='validate')payload={valid:true};return {version:1,taskId:req.taskId,fence:req.fence,phase:req.phase,itemId:req.itemId,stageAttempt:req.attempt,sequence:1,inputHash:req.inputHash,outputHash:hashKnowledgePayload(payload),payload,evidence:[{path:'readme.md',hash:sources[0].hash,startLine:1,endLine:1,kind:'read'}],dependencies:[],disposition:'prepared'};};const c=new KnowledgeKernelCoordinator({store,project,bindModel:async()=>binding,executeStage,abortStage:async()=>{},pipelineConfigHash});
 try{const expectedModelIdentity=knowledgeModelIdentity(binding);const first=await c.start({version:1,requestId:'invalid',projectId:p.id,domain:'wiki',language:'en',intent:'generate',confirmExternal:true,expectedModelIdentity,expectedPlanToken:source.planToken});await viWait(()=>store.getTask(first.run!.taskId)?.state==='failed');const parent=store.getTask(first.run!.taskId)!;const failedItem=store.listItems(parent.id).find(item=>item.phase==='generate'&&item.state==='failed');if(!failedItem)throw new Error(JSON.stringify({job:parent,items:store.listItems(parent.id)}));const candidate=store.readFailedCandidate({taskId:parent.id,phase:'generate',itemId:failedItem.itemId});expect(candidate.error.code).toBe('INVALID_PAGE_LINK');expect(candidate.payload).toMatchObject({markdown:'[Missing](../../missing.md)'});expect(store.listItems(parent.id).every(item=>item.state!=='running')).toBe(true);expect(store.listCheckpoints(parent.id).some(item=>item.itemId===failedItem.itemId)).toBe(false);bad=false;const repaired=await c.act({version:1,requestId:'repair',taskId:parent.id,expectedRevision:parent.metadata!.repoWiki!.revision,action:'repair',confirmExternal:true,expectedModelIdentity});await viWait(()=>store.getTask(repaired.run!.taskId)?.state==='completed');expect(generated).toBe(2);expect(store.readCheckpoint({taskId:repaired.run!.taskId,phase:'generate',itemId:failedItem.itemId}).payload).toMatchObject({markdown:'# Intro'});}
 finally{await c.close();engine.close();db.close();rmSync(base,{recursive:true,force:true});}
},30000);

it.each([[false,'failed'],[true,'failed'],[false,'blocked'],[true,'blocked']] as const)('sanitizes returned v2=%s disposition=%s stage diagnostics',async(useV2,disposition)=>{
 const base=mkdtempSync(join(tmpdir(),'knowledge-returned-error-')),root=join(base,'src');mkdirSync(root);writeFileSync(join(root,'readme.md'),'# project\n');const engine=new WorkspaceEngine(join(base,'data'));const db=new DatabaseSync(':memory:');const store=new KnowledgeBuildStore(db,{controllerEpoch:'epoch'});const project=new KnowledgeProjectPort(engine);const p=engine.create_project(root,'en');const source=await project.prepare(p.id,'wiki');
 const executeStage=async(req:StageExecutionRequest):Promise<StageExecutionResult>=>({version:1,taskId:req.taskId,fence:req.fence,phase:req.phase,itemId:req.itemId,stageAttempt:req.attempt,sequence:1,inputHash:req.inputHash,outputHash:hashKnowledgePayload(null),payload:null,evidence:[],dependencies:[],disposition,error:{code:disposition==='blocked'?'BUDGET_EXHAUSTED':'MODEL_ERROR',message:'C:\\private\\secret.md?token=hidden',retriable:true}});
 const c=new KnowledgeKernelCoordinator({store,project,bindModel:async()=>binding,executeStage,abortStage:async()=>{},pipelineConfigHash:useV2?'knowledge-kernel-qoder-v2':'knowledge-kernel-v1'});
 try{const started=await c.start({version:1,requestId:'returned',projectId:p.id,domain:'wiki',language:'en',intent:'generate',confirmExternal:true,expectedModelIdentity:knowledgeModelIdentity(binding),expectedPlanToken:source.planToken});await viWait(()=>store.getTask(started.run!.taskId)?.state===disposition);const job=store.getTask(started.run!.taskId)!;const item=store.listItems(job.id).find(i=>i.phase==='overview')!;expect(item.state).toBe(disposition);const saved=JSON.parse((db.prepare('SELECT error FROM knowledge_build_items WHERE task_id=? AND phase=?').get(job.id,'overview') as {error:string}).error);expect(saved).toMatchObject({code:disposition==='blocked'?'BUDGET_EXHAUSTED':'MODEL_ERROR',retriable:true});for(const value of [JSON.stringify(saved),JSON.stringify(job.metadata?.repoWiki?.error)]){expect(value).not.toContain('secret.md');expect(value).not.toContain('hidden');}}
 finally{await c.close();engine.close();db.close();rmSync(base,{recursive:true,force:true});}
},30000);

it.each([[false,false],[true,false],[false,true],[true,true]])('settles pause safely (v2=%s, prepared=%s)',async (useV2,completed)=>{
 const base=mkdtempSync(join(tmpdir(),'knowledge-pause-return-')),root=join(base,'src');mkdirSync(root);writeFileSync(join(root,'readme.md'),'# project\n');const engine=new WorkspaceEngine(join(base,'data'));const db=new DatabaseSync(':memory:');const store=new KnowledgeBuildStore(db,{controllerEpoch:'epoch'});const project=new KnowledgeProjectPort(engine);const p=engine.create_project(root,'en');const source=await project.prepare(p.id,'wiki');let waiting=false;
 const executeStage=async(req:StageExecutionRequest,signal:AbortSignal):Promise<StageExecutionResult>=>{const sources=[{path:'readme.md',hash:source.source.hashes['readme.md'],start:1,end:1}];if(req.phase==='plan'){waiting=true;await new Promise<void>(resolve=>signal.addEventListener('abort',()=>resolve(),{once:true}));return {version:1,taskId:req.taskId,fence:req.fence,phase:req.phase,itemId:req.itemId,stageAttempt:req.attempt,sequence:1,inputHash:req.inputHash,outputHash:hashKnowledgePayload(completed?{items:[{id:'intro',title:'Intro',goal:'Explain',dependencies:[]}]}:null),payload:completed?{items:[{id:'intro',title:'Intro',goal:'Explain',dependencies:[]}]}:null,evidence:[],dependencies:[],disposition:completed?'prepared':'failed',...(completed?{}:{error:{code:'MODEL_ERROR',message:'aborted',retriable:false}})};}const payload={summary:'Project',sources};return {version:1,taskId:req.taskId,fence:req.fence,phase:req.phase,itemId:req.itemId,stageAttempt:req.attempt,sequence:1,inputHash:req.inputHash,outputHash:hashKnowledgePayload(payload),payload,evidence:[{path:'readme.md',hash:sources[0].hash,startLine:1,endLine:1,kind:'read'}],dependencies:[],disposition:'prepared'};};
 const c=new KnowledgeKernelCoordinator({store,project,bindModel:async()=>binding,executeStage,abortStage:async()=>{},pipelineConfigHash:useV2?'knowledge-kernel-qoder-v2':'knowledge-kernel-v1'});
 try{const started=await c.start({version:1,requestId:'pause-return',projectId:p.id,domain:'wiki',language:'en',intent:'generate',confirmExternal:true,expectedModelIdentity:knowledgeModelIdentity(binding),expectedPlanToken:source.planToken});await viWait(()=>waiting);const before=store.getTask(started.run!.taskId)!;const paused=await c.act({version:1,requestId:'pause-return-action',taskId:before.id,expectedRevision:before.metadata!.repoWiki!.revision,action:'pause'});expect(paused.run?.state).toBe('paused');const job=store.getTask(before.id)!;expect(job.metadata?.repoWiki?.counts.failed).toBe(0);expect(store.listItems(job.id).find(i=>i.phase==='plan')?.state).toBe(completed?'prepared':'running');expect(store.listCheckpoints(job.id).some(i=>i.phase==='overview')).toBe(true);}
 finally{await c.close();engine.close();db.close();rmSync(base,{recursive:true,force:true});}
},30000);

