 const base=mkdtempSync(join(tmpdir(),'knowledge-stage-error-')),root=join(base,'src');mkdirSync(root);writeFileSync(join(root,'readme.md'),'# project\n');const engine=new WorkspaceEngine(join(base,'data'));const db=new DatabaseSync(':memory:');const store=new KnowledgeBuildStore(db,{controllerEpoch:'epoch'});const project=new KnowledgeProjectPort(engine);const p=engine.create_project(root,'en');const source=await project.prepare(p.id,'wiki');const pipelineConfigHash=useV2?'knowledge-kernel-qoder-v2':'knowledge-kernel-v1';
 const executeStage=async(req:StageExecutionRequest):Promise<StageExecutionResult>=>{if(req.phase==='overview')throw new Error('C:\\private\\repo\\secret.md?token=hidden');let payload:unknown={valid:true};return {version:1,taskId:req.taskId,fence:req.fence,phase:req.phase,itemId:req.itemId,stageAttempt:req.attempt,sequence:1,inputHash:req.inputHash,outputHash:hashKnowledgePayload(payload),payload,evidence:[],dependencies:[],disposition:'prepared'};};const c=new KnowledgeKernelCoordinator({store,project,bindModel:async()=>binding,executeStage,abortStage:async()=>{},pipelineConfigHash});
 try{const started=await c.start({version:1,requestId:'throw',projectId:p.id,domain:'wiki',language:'en',intent:'generate',confirmExternal:true,expectedModelIdentity:knowledgeModelIdentity(binding),expectedPlanToken:source.planToken});await viWait(()=>store.getTask(started.run!.taskId)?.state==='failed');const job=store.getTask(started.run!.taskId)!;expect(store.listItems(job.id).find(item=>item.phase==='overview')?.state).toBe('failed');expect(store.listItems(job.id).some(item=>item.state==='running')).toBe(false);expect(job.metadata?.repoWiki?.error?.message).not.toContain('secret.md');expect(job.metadata?.repoWiki?.error?.message).not.toContain('hidden');}
 finally{await c.close();engine.close();db.close();rmSync(base,{recursive:true,force:true});}
